  'site.services.p9': 'அலுவலக கட்டிடங்கள்',
  'site.services.p10': 'சில்லறை & காட்சியறைகள்',
  'site.services.p11': 'கிடங்குகள்',
  'site.services.p12': 'தொழிற்சாலைகள் & ஆலைகள்',
  'site.services.p13': 'கட்டமைப்பு மறுசீரமைப்பு',
  'site.services.p14': 'முகப்பு மேம்பாடுகள்',
  'site.services.p15': 'உள்துறை மறுவடிவமைப்பு',
  'site.services.p16': 'மறுசீரமைப்பு',
  'site.services.p17': 'விற்பனையாளர் மேலாண்மை',
  'site.services.p18': 'தர ஆய்வுகள்',
