  'site.services.p23': 'சூரிய & பசுமை ஆற்றல்',
  'site.services.p24': 'ஸ்மார்ட் ஹோம் ஒருங்கிணைப்பு',
  'site.services.cta': 'இந்த சேவைக்கான மதிப்பீட்டைப் பெறுங்கள்',
  'site.process.hero.eyebrow': 'எங்கள் செயல்முறை',
  'site.process.hero.title': 'ஆறு படிகள். பூஜ்ஜிய ஆச்சரியங்கள்.',
  'site.process.hero.highlight': 'அதுவே வாக்குறுதி.',
  'site.process.hero.sub': 'உங்கள் முதல் அழைப்பிலிருந்து சாவிகள் ஒப்படைக்கும் நாள் வரை வெளிப்படையான, மைல்கல் அடிப்படையிலான பயணம்.',
  'site.projects.hero.eyebrow': 'திட்டங்கள்',
  'site.projects.hero.title': 'நிறைவேற்றப்பட்ட வாக்குறுதிகளில்',
  'site.projects.hero.highlight': 'கட்டப்பட்ட தொகுப்பு.',
  'site.projects.hero.sub': 'இந்தியா முழுவதும் வீடுகள், பணியிடங்கள் மற்றும் நகர உள்கட்டமைப்பு — ஒவ்வொரு வழங்கலுக்குப் பின்னால் உள்ள பணி மற்றும் எண்களை ஆராயுங்கள்.',
  'site.testi.hero.eyebrow': 'வாடிக்கையாளர் கருத்துகள்',
  'site.testi.hero.title': 'எங்களை நம்பியவர்களிடமிருந்து',
  'site.testi.hero.highlight': 'கேளுங்கள்.',
  'site.testi.hero.sub': 'ஒரு தசாப்த வழங்கல் எப்படி இருக்கும் என்பது இதோ — வீட்டு உரிமையாளர்கள், வணிகத் தலைவர்கள் மற்றும் வசதி தலைவர்கள்.',
  'site.why.hero.eyebrow': 'ஏன் எங்களைத் தேர்வு செய்ய வேண்டும்',
  'site.why.hero.title': 'நாங்கள் வெறுமனே கட்டுவதில்லை.',
  'site.why.hero.highlight': 'ஒவ்வொன்றுக்கும் கணக்குக் காட்டுகிறோம்.',
  'site.why.hero.sub': 'பில்டரைத் தேர்ந்தெடுப்பது நம்பிக்கையின் பாய்ச்சல். அதை ஆவணப்படுத்தப்பட்ட, தணிக்கை செய்யப்பட்ட, உத்தரவாதமுள்ள முடிவாக்குகிறோம்.',
  'site.why.compare.eyebrow': 'வித்தியாசம்',
