  'site.why.cmp1': 'வெளிப்படையான வரி-உருப்படி விலை நிர்ணயம்',
  'site.why.cmp2': 'வாடிக்கையாளர்களுக்கான நேரடி திட்ட டாஷ்போர்டு',
  'site.why.cmp3': 'உள் கட்டிடக்கலைஞர்கள் & பொறியாளர்கள்',
