  'site.estimate.title': 'உங்கள் கட்டுமான பட்ஜெட்டை மதிப்பிடுங்கள்',
  'site.estimate.sub': 'உங்கள் நிலப் பரப்பளவு, திட்டமிட்ட தளங்கள் மற்றும் பூச்சு நிலையை உள்ளிடவும். இந்த கணக்கீடு CREWNBUILD உரிமையாளர் மதிப்பீட்டு பணிப்பாய்வு போன்ற அதே கட்டுமான விகித தர்க்கத்தைப் பயன்படுத்துகிறது.',
