  'award.confirmFinalQuotationSub': 'இறுதி மேற்கோளை உறுதிப்படுத்துங்கள். நீங்கள் உறுதிப்படுத்திய பிறகே உரிமையாளர் திட்டத்தை ஒதுக்க முடியும்.',
  'award.confirmQuotation': 'இறுதி மேற்கோளை உறுதிப்படுத்து — {amount}',
  'award.dialog.confirmQuotationTitle': 'இறுதி மேற்கோளை உறுதிப்படுத்துங்கள்',
  'award.dialog.confirmQuotationBody': 'உறுதிப்படுத்துவதன் மூலம், இந்தத் திட்டத்தை {amount} தொகைக்கு ஏற்க ஒப்புக்கொள்கிறீர்கள். பின்னர் உரிமையாளர் இதை உங்களுக்கு ஒதுக்குவதா என்று முடிவு செய்வார்; அவர் ஒதுக்கும் வரை எதுவும் ஒதுக்கப்படாது.',
