  'landing.world.label': 'CREWNBUILD உலகம்',
  'landing.world.headline': 'கட்டுமானத்தின் பின்னால்',
  'landing.world.highlight': 'இருக்கும் மனிதர்கள்.',
  'landing.world.body': 'கட்டுமானம் என்பது மனிதர்கள், முடிவுகள், நேரம் மற்றும் நம்பிக்கை. CREWNBUILD ஒவ்வொருவருக்கும் இணைவதற்கும், பங்களிப்பதற்கும், திட்டத்தை முன்னோக்கி நகர்த்துவதற்கும் தெளிவான இடத்தை அளிக்கிறது.',
