  'landing.world.notes.2': 'வளங்கள்',
  'landing.final.label': 'உங்கள் அடுத்த அடி',
  'landing.final.headline': 'சிறந்ததைக் கட்ட',
  'landing.final.highlight': 'தயாரா?',
  'landing.final.body': 'உங்களுக்குத் தேவையான நபர்கள், பொருட்கள் மற்றும் வளங்கள் — அனைத்தையும் ஒரே இடத்தில் கண்டறியுங்கள்.',
  'landing.final.speech': 'கட்டத் தொடங்குவோம்!',
  'landing.freeEstimate.button': 'இலவச மதிப்பீட்டைப் பெறுங்கள்',
  'landing.footer.tagline': 'இந்தியாவிற்கான இணைக்கப்பட்ட கட்டுமான தளம். கட்டுவதற்கு உங்களுக்குத் தேவையான அனைத்தும் — வீட்டு உரிமையாளர்கள், கட்டுநர்கள், பொறியாளர்கள், சப்ளையர்கள் மற்றும் உபகரண உரிமையாளர்கள், அனைவரும் ஒரே இடத்தில்.',
