  'landing.footer.language': 'மொழி',
  'landing.comingSoonPage.eyebrow': 'விரைவில் வருகிறது',
  'landing.comingSoonPage.headline': 'இன்னும் பதிவுக்கு',
  'landing.comingSoonPage.highlight': 'திறக்கப்படவில்லை.',
  'landing.comingSoonPage.body': 'CREWNBUILD இன் மற்ற பகுதிகள் தயாராக உங்களுக்காகக் காத்திருக்கின்றன. இன்றே தொடங்க வேறு ஒரு பங்கைத் தேர்ந்தெடுங்கள் — இது விரைவில் திறக்கும்.',
