  'landing.roles.0.questions.1': 'சரியான கட்டுநர்கள், பொறியாளர்கள் மற்றும் கட்டுமான சேவைகளைத் தேடுகிறீர்களா?',
  'landing.roles.1.title': 'கட்டுநர்',
