  'site.calculators.vastu.overall.excellent': 'சிறப்பானது',
  'site.calculators.vastu.overall.good': 'நல்லது',
  'site.calculators.vastu.overall.attention': 'கவனம் தேவை',
  'site.calculators.vastu.adviceFavourable': 'இதற்குப் பரிந்துரைக்கப்பட்ட இடங்களில் {direction} ஒன்றாகும்.',
  'site.calculators.vastu.advicePreferred': 'பாரம்பரியமாக விரும்பப்படுவது: {best}. {principle}',
  'site.calculators.vastu.or': ' அல்லது ',
  'site.calculators.vastu.title': 'வாஸ்து கால்குலேட்டர்',
  'site.calculators.vastu.intro': 'உங்கள் வீட்டின் ஒவ்வொரு பகுதியும் எந்தத் திசையில் உள்ளது என்பதைத் தேர்ந்தெடுத்து, பாரம்பரிய வாஸ்து திசைக் கோட்பாடுகளுக்கு எதிராக அந்த அமைவுகள் எப்படி மதிப்பெண் பெறுகின்றன என்பதைப் பாருங்கள்.',
  'site.calculators.vastu.optional': '(விருப்பத்தேர்வு)',
