  'site.calculators.plan.errType': 'வரைபடத்தை JPG அல்லது PNG படமாகப் பதிவேற்றவும். PDF வரைபடங்கள் இங்கு ஆதரிக்கப்படவில்லை — முதலில் அந்தப் பக்கத்தைப் படமாக ஏற்றுமதி செய்யவும்.',
