  'site.calculators.plan.headline': 'வாஸ்து இணக்கம் — உங்கள் வரைபடத்திலிருந்து',
  'site.calculators.plan.headlineSub': '{name} மீது குறியிடப்பட்ட {count} அறையின் அடிப்படையில்',
  'site.calculators.plan.headlineSubPlural': '{name} மீது குறியிடப்பட்ட {count} அறைகளின் அடிப்படையில்',
